use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let jobs: Vec<Vec<i64>> = input.as_array().unwrap().iter().map(|v| {
        let arr = v.as_array().unwrap();
        vec![arr[0].as_i64().unwrap(), arr[1].as_i64().unwrap()]
    }).collect();

    let mut finish_times = Vec::new();
    let mut current_time = 0;

    for job in jobs {
        let arrival = job[0];
        let duration = job[1];

        if arrival > current_time {
            current_time = arrival;
        }

        current_time += duration;
        finish_times.push(current_time);
    }

    serde_json::Value::Array(finish_times.into_iter().map(|t| serde_json::Value::Number(t.into())).collect())
}
